   }
   if(MODE=="rail"){
    depot=Step(a,PLATFORM+1,0);local f=Step(a,PLATFORM,0);
    if(!GSRail.BuildRailDepot(depot,f) || !GSRail.BuildRailTrack(f,GSRail.RAILTRACK_NE_SW)){Fail("rail depot connection");return null;}
   }else{
    foreach(t in path){
     if(GSStation.IsValidStation(GSStation.GetStationID(t)))continue;
     foreach(delta in [[0,1],[0,-1],[1,0],[-1,0]]){
      if(depot>=0)break;
      local d=Step(t,delta[0],delta[1]);if(!GSTile.IsBuildable(d))continue;
      local tm=GSTestMode(),ok=GSRoad.BuildRoadDepot(d,t);tm=null;
      if(ok){local check=GSTestMode();ok=GSRoad.BuildRoad(t,d);check=null;}
      if(ok && GSRoad.BuildRoadDepot(d,t)){
       if(!GSRoad.BuildRoad(t,d) && GSError.GetLastErrorString()!="ERR_ALREADY_BUILT"){Fail("road depot connection");return null;}
       depot=d;
      }
     }
     if(depot>=0)break;
    }
   }
  }

  if(depot<0 && MODE=="road"){
   for(local radius=1;radius<=16 && depot<0;radius++)foreach(delta in [[radius,0],[-radius,0],[0,radius],[0,-radius]]){
    if(depot>=0)break;
    local d=Step(a,delta[0],delta[1]),front=Step(d,-1,0);
    if(!GSTile.IsBuildable(d) || (!GSTile.IsBuildable(front) && !GSRoad.IsRoadTile(front)))continue;
