      if(!GSBridge.IsBridgeTile(branch[i]))GSRoad.BuildRoad(branch[i],next);
     }else GSRoad.BuildRoad(branch[i],next);
    }
    GSLog.Info("P4_DEPOT_SPUR|"+CASE+"|"+branch.len());
   }
  }
  if(depot<0){Fail("depot");return null;}
  GSLog.Info("P4_CAPITAL|"+CASE+"|way_and_depot|"+(afterb-GSCompany.GetBankBalance(CID)));
  local infra=initialcash-GSCompany.GetBankBalance(CID),prefleet=GSCompany.GetBankBalance(CID);account.ResetCosts();
  local v=(MODE=="rail"?GSVehicle.BuildVehicle(depot,ENGINE):GSVehicle.BuildVehicleWithRefit(depot,ENGINE,CARGO));
