  GSLog.Info("P4_BUILT|"+CASE+"|"+ENGINE+"|"+GSEngine.GetName(ENGINE)+"|"+infra+"|"+fleet+"|"+GSVehicle.GetCapacity(v,CARGO)+"|"+GSMap.GetTileX(a)+"|"+GSMap.GetTileY(a)+"|"+GSMap.GetTileX(b)+"|"+GSMap.GetTileY(b)+"|"+(path==null?-1:path.len())+"|"+GSCompany.GetBankBalance(CID)+"|"+GSCompany.GetLoanAmount()+"|"+GSDate.GetCurrentDate());
