   if(GSBridge.IsBridgeTile(cur) && GSBridge.GetOtherBridgeEnd(cur)==next)return true;
   if(GSTunnel.IsTunnelTile(cur) && GSTunnel.GetOtherTunnelEnd(cur)==next)return true;
