 function Step(t,dx,dy){return Tile(GSMap.GetTileX(t)+dx,GSMap.GetTileY(t)+dy);}
 function DockWater(t){foreach(d in [[1,0],[-1,0],[0,1],[0,-1]]){local n=Step(t,d[0],d[1]);if(GSMarine.IsDockTile(n))return Step(n,d[0],d[1]);}for(local r=1;r<=4;r++)foreach(d in [[r,0],[-r,0],[0,r],[0,-r]]){local n=Step(t,d[0],d[1]);if(GSTile.IsWaterTile(n))return n;}return t;}
 function WaterComponent(start,goal){
  local queue=[start],seen={},pos=0;seen[start]<-true;
  while(pos<queue.len() && pos<350000){local t=queue[pos++];if(t==goal)break;
   foreach(d in [[1,0],[-1,0],[0,1],[0,-1]]){local n=Step(t,d[0],d[1]);if(n in seen || GSMap.DistanceManhattan(start,n)>700)continue;
    if(GSMarine.AreWaterTilesConnected(t,n)){seen[n]<-true;queue.append(n);}
   }
  }
  GSLog.Info("P3_WATER|"+start+"|"+goal+"|"+seen.len()+"|"+(goal in seen));return seen;
 }
 function Link(prev,cur,next){
  if(MODE=="road" && (GSMap.DistanceManhattan(cur,next)>1 || GSMap.DistanceManhattan(prev,cur)>1)){
   local px=GSMap.GetTileX(prev)-GSMap.GetTileX(cur),py=GSMap.GetTileY(prev)-GSMap.GetTileY(cur),nx=GSMap.GetTileX(next)-GSMap.GetTileX(cur),ny=GSMap.GetTileY(next)-GSMap.GetTileY(cur);
   if(px*ny!=py*nx || px*nx+py*ny>=0)return false;
  }
  if(MODE=="road" && GSMap.DistanceManhattan(cur,next)>1){
   if(GSBridge.IsBridgeTile(cur) && GSBridge.GetOtherBridgeEnd(cur)==next)return true;
   if(GSTunnel.IsTunnelTile(cur) && GSTunnel.GetOtherTunnelEnd(cur)==next)return true;
   local test=GSTestMode(),ok=GSBridge.BuildBridge(GSVehicle.VT_ROAD,0,cur,next);test=null;return ok;
  }
  if(MODE=="road" && GSTile.GetSlope(cur)!=GSTile.SLOPE_FLAT && (GSMap.GetTileX(prev)+GSMap.GetTileX(next)!=2*GSMap.GetTileX(cur) || GSMap.GetTileY(prev)+GSMap.GetTileY(next)!=2*GSMap.GetTileY(cur)))return false;
  local test=GSTestMode();
  local ok=MODE=="rail"?GSRail.BuildRail(prev,cur,next):GSRoad.BuildRoad(cur,next);
  if(!ok && GSError.GetLastErrorString()=="ERR_ALREADY_BUILT")ok=true;
  test=null;return ok;
 }
 function Path(start,previous,goal){
  local nodes=[{tile=start,prev=previous,backidx=-1}],seen={},pos=0;
  seen[previous+"_"+start]<-true;
  local xmin=min(GSMap.GetTileX(start),GSMap.GetTileX(goal))-14,xmax=max(GSMap.GetTileX(start),GSMap.GetTileX(goal))+14;
  local ymin=min(GSMap.GetTileY(start),GSMap.GetTileY(goal))-14,ymax=max(GSMap.GetTileY(start),GSMap.GetTileY(goal))+14;
  while(pos<nodes.len() && pos<30000){
   local node=nodes[pos];
   if(node.tile==goal && Link(node.prev,goal,Step(goal,MODE=="rail"?-1:1,0))){local path=[];local i=pos;while(i>=0){path.insert(0,nodes[i].tile);i=nodes[i].backidx;}return path;}
   local adjacent=[];
   foreach(delta in [[1,0],[-1,0],[0,1],[0,-1]]){
    local n=Step(node.tile,delta[0],delta[1]);adjacent.append(n);
    if(MODE=="road" && GSTile.IsWaterTile(n))for(local length=2;length<=12;length++){
     local end=Step(node.tile,delta[0]*length,delta[1]*length);
     if(!GSTile.IsWaterTile(end)){adjacent.append(end);break;}
    }
   }
   if(MODE=="road" && GSRoad.HasRoadType(node.tile,GSRoad.GetCurrentRoadType())){
    if(GSBridge.IsBridgeTile(node.tile))adjacent.append(GSBridge.GetOtherBridgeEnd(node.tile));
    if(GSTunnel.IsTunnelTile(node.tile))adjacent.append(GSTunnel.GetOtherTunnelEnd(node.tile));
   }
   foreach(next in adjacent){
    local x=GSMap.GetTileX(next),y=GSMap.GetTileY(next);
    if(x<xmin || x>xmax || y<ymin || y>ymax || x<1 || y<1)continue;
    local key=node.tile+"_"+next;
    if(MODE=="rail" && GSRail.IsRailStationTile(next))continue;
    if(next==node.prev || key in seen)continue;
    local ancestor=pos,repeated=false;
    while(ancestor>=0){
     if(nodes[ancestor].tile==next){repeated=true;break;}
     ancestor=nodes[ancestor].backidx;
    }
    if(repeated)continue;
    seen[key]<-true;
    if(!Link(node.prev,node.tile,next))continue;
    nodes.append({tile=next,prev=node.tile,backidx=pos});
   }
   pos++;
  }
  GSLog.Info("P3_PATH_FAILURE|"+pos+"|"+nodes.len());return null;
 }
 function Candidates(id,production){
  local list=[];
  if(ENDPOINTS=="industry"){
   local tiles=production?GSTileList_IndustryProducing(id,MODE=="road"?3:4):GSTileList_IndustryAccepting(id,MODE=="road"?3:4);
   foreach(tile,v in tiles)list.append(tile);
  }else{
   local t=GSTown.GetLocation(id),x=GSMap.GetTileX(t),y=GSMap.GetTileY(t);
   for(local dx=-14;dx<=14;dx++)for(local dy=-14;dy<=14;dy++){
    local tile=Tile(x+dx,y+dy);
    if(GSTile.GetCargoAcceptance(tile,CARGO,1,1,MODE=="ship"?5:3)>=8 && GSTile.GetCargoProduction(tile,CARGO,1,1,MODE=="ship"?5:3)>0)list.append(tile);
   }
  }
  local center=ENDPOINTS=="industry"?GSIndustry.GetLocation(id):GSTown.GetLocation(id);
  list.sort(function(a,b):(center){return GSMap.DistanceManhattan(a,center)-GSMap.DistanceManhattan(b,center);});
  return list;
 }
 function Station(id,production){
  foreach(tile in Candidates(id,production)){
   if("straight_local" in ACTIVE && ACTIVE.straight_local){
    if(production){local lane=true;for(local dx=0;dx<=MIN_SEPARATION+1;dx++)if(!GSRoad.IsRoadTile(Step(tile,-dx,0)))lane=false;if(!lane)continue;}
    else if(GSMap.GetTileY(tile)!=GSMap.GetTileY(origin_tile) || GSMap.GetTileX(tile)!=GSMap.GetTileX(origin_tile)-MIN_SEPARATION)continue;
   }
   if(!production && origin_tile>=0 && GSMap.DistanceManhattan(tile,origin_tile)<MIN_SEPARATION)continue;
   if(MODE=="ship"){
    if(ENDPOINTS=="industry" && GSIndustry.HasDock(id))return GSIndustry.GetDockLocation(id);
    if(!GSTile.IsCoastTile(tile))continue;
    local near=false;if("dock_spacing" in CONFIG)foreach(t in DOCK_TILES)if(GSMap.DistanceManhattan(t,tile)<CONFIG.dock_spacing)near=true;
    if("clear_approaches" in CONFIG)foreach(t in DEPOT_TILES)if(GSMap.DistanceManhattan(t,tile)<5)near=true;
    if(near)continue;
    local tm=GSTestMode(),ok=GSMarine.BuildDock(tile,GSStation.STATION_NEW);tm=null;
    if(ok && GSMarine.BuildDock(tile,GSStation.STATION_NEW)){DOCK_TILES.append(tile);return tile;}
   }else{
    if(!GSTile.IsBuildable(tile) && !(MODE=="road" && GSRoad.IsRoadTile(tile)))continue;
    if(MODE=="road" && !GSTile.IsBuildable(Step(tile,-1,0)) && !GSRoad.IsRoadTile(Step(tile,-1,0)))continue;
    if(MODE=="road" && !GSTile.IsBuildable(Step(tile,1,0)) && !GSRoad.IsRoadTile(Step(tile,1,0)))continue;
    if(MODE=="rail"){
     local clear=true;for(local dx=-2;dx<=PLATFORM+1;dx++)if(!GSTile.IsBuildable(Step(tile,dx,0)))clear=false;
     if(!clear)continue;
    }
    local front=Step(tile,-1,0),tm=GSTestMode();
    local ok=MODE=="rail"?GSRail.BuildRailStation(tile,GSRail.RAILTRACK_NE_SW,1,PLATFORM,GSStation.STATION_NEW):GSRoad.BuildDriveThroughRoadStation(tile,front,CARGO==0?GSRoad.ROADVEHTYPE_BUS:GSRoad.ROADVEHTYPE_TRUCK,GSStation.STATION_NEW);
    tm=null;
    if(!ok)continue;
    if(!production && origin_tile>=0){
     local trial=Path(Step(origin_tile,-1,0),origin_tile,Step(tile,MODE=="rail"?PLATFORM:-1,0));
     if(trial==null)continue;
    }
    ok=MODE=="rail"?GSRail.BuildRailStation(tile,GSRail.RAILTRACK_NE_SW,1,PLATFORM,GSStation.STATION_NEW):GSRoad.BuildDriveThroughRoadStation(tile,front,CARGO==0?GSRoad.ROADVEHTYPE_BUS:GSRoad.ROADVEHTYPE_TRUCK,GSStation.STATION_NEW);
    if(ok)return tile;
   }
  }
  return -1;
 }
 function Build(){  local before=Ledger(CID);

  GSLog.Info("P4_CASE|"+CASE+"|"+MODE+"|"+CARGO+"|"+A+"|"+B+"|"+GSDate.GetCurrentDate());
  while(GSCompany.ResolveCompanyID(CID)==GSCompany.COMPANY_INVALID)Sleep(2);
  local mode=GSCompanyMode(CID),account=GSAccounting(),initialcash=GSCompany.GetBankBalance(CID);
  GSLog.Info("P4_INITIAL|"+GSCompany.GetBankBalance(CID)+"|"+GSCompany.GetLoanAmount()+"|"+GSCompany.GetMaxLoanAmount()+"|"+GSGameSettings.GetValue("economy.infrastructure_maintenance")+"|"+GSGameSettings.GetValue("vehicle.max_train_length"));
  if(MODE=="rail")GSRail.SetCurrentRailType(GSEngine.GetRailType(ENGINE));
  if(MODE=="road")GSRoad.SetCurrentRoadType(GSEngine.GetRoadType(ENGINE));
  local a=Station(A,true);if(a<0){Fail("origin station");return null;}
  origin_tile=a;
  local aftera=GSCompany.GetBankBalance(CID);GSLog.Info("P4_CAPITAL|"+CASE+"|origin_station|"+(initialcash-aftera));
  local b=Station(B,false);if(b<0){Fail("destination station");return null;}
  local afterb=GSCompany.GetBankBalance(CID);GSLog.Info("P4_CAPITAL|"+CASE+"|destination_station|"+(aftera-afterb));
  local depot=-1,path=null;
  if(MODE=="ship"){
   local water=WaterComponent(DockWater(a),DockWater(b));if(!(DockWater(b) in water)){Fail("docks not connected within 200-tile water search");return null;}
   local x=GSMap.GetTileX(a),y=GSMap.GetTileY(a);
   for(local dx=-14;dx<=14 && depot<0;dx++)for(local dy=-14;dy<=14 && depot<0;dy++){
    local t=Tile(x+dx,y+dy),f=Step(t,1,0);
    local crowded=false;if("depot_spacing" in CONFIG)foreach(old in DEPOT_TILES)if(GSMap.DistanceManhattan(t,old)<CONFIG.depot_spacing)crowded=true;
    if("clear_approaches" in CONFIG)foreach(old in DOCK_TILES)if(GSMap.DistanceManhattan(t,old)<5)crowded=true;
    if(!crowded && t in water && f in water && GSTile.IsWaterTile(t) && GSTile.IsWaterTile(f)){
     local tm=GSTestMode(),ok=GSMarine.BuildWaterDepot(t,f);tm=null;
     if(ok && GSMarine.BuildWaterDepot(t,f)){depot=t;DEPOT_TILES.append(t);}
    }
   }
  }else{
   local start=Step(a,-1,0),previous=a,goal=MODE=="rail"?Step(b,PLATFORM,0):Step(b,-1,0);
   path=Path(start,previous,goal);if(path==null){Fail("no legal contiguous route");return null;}
   local prev=previous;
   for(local i=0;i<path.len();i++){
    local next=i+1<path.len()?path[i+1]:(MODE=="rail"?Step(b,PLATFORM-1,0):b);
    local ok=false;
    if(MODE=="rail")ok=GSRail.BuildRail(prev,path[i],next);
    else if(GSMap.DistanceManhattan(path[i],next)>1){
     if(GSBridge.IsBridgeTile(path[i]) && GSBridge.GetOtherBridgeEnd(path[i])==next)ok=true;
     else if(GSTunnel.IsTunnelTile(path[i]) && GSTunnel.GetOtherTunnelEnd(path[i])==next)ok=true;
     else ok=GSBridge.BuildBridge(GSVehicle.VT_ROAD,0,path[i],next);
    }else ok=GSRoad.BuildRoad(path[i],next);
    if(!ok && GSError.GetLastErrorString()!="ERR_ALREADY_BUILT"){GSLog.Info("P4_COMMIT_FAILURE|"+i+"|"+prev+"|"+path[i]+"|"+next);Fail("commit path");return null;}
    prev=path[i];
   }
   if(MODE=="road"){
    GSRoad.BuildRoad(a,Step(a,-1,0));
    GSRoad.BuildRoad(a,Step(a,1,0));
    GSRoad.BuildRoad(b,Step(b,1,0));
   }
   if(MODE=="rail"){
    depot=Step(a,PLATFORM+1,0);local f=Step(a,PLATFORM,0);
    if(!GSRail.BuildRailDepot(depot,f) || !GSRail.BuildRailTrack(f,GSRail.RAILTRACK_NE_SW)){Fail("rail depot connection");return null;}
   }else{
    foreach(t in path){
     if(GSStation.IsValidStation(GSStation.GetStationID(t)))continue;
     foreach(delta in [[0,1],[0,-1],[1,0],[-1,0]]){
      if(depot>=0)break;
      local d=Step(t,delta[0],delta[1]);if(!GSTile.IsBuildable(d))continue;
      local tm=GSTestMode(),ok=GSRoad.BuildRoadDepot(d,t);tm=null;
      if(ok){local check=GSTestMode();ok=GSRoad.BuildRoad(t,d);check=null;}
      if(ok && GSRoad.BuildRoadDepot(d,t)){
       if(!GSRoad.BuildRoad(t,d) && GSError.GetLastErrorString()!="ERR_ALREADY_BUILT"){Fail("road depot connection");return null;}
       depot=d;
      }
     }
     if(depot>=0)break;
    }
   }
  }

  if(depot<0 && MODE=="road"){
   for(local radius=1;radius<=16 && depot<0;radius++)foreach(delta in [[radius,0],[-radius,0],[0,radius],[0,-radius]]){
    if(depot>=0)break;
    local d=Step(a,delta[0],delta[1]),front=Step(d,-1,0);
    if(!GSTile.IsBuildable(d) || (!GSTile.IsBuildable(front) && !GSRoad.IsRoadTile(front)))continue;
    local tm=GSTestMode(),ok=GSRoad.BuildRoadDepot(d,front);tm=null;
    if(!ok)continue;
    local branch=Path(Step(a,-1,0),a,front);if(branch==null)continue;
    if(!GSRoad.BuildRoadDepot(d,front))continue;
    depot=d;
    for(local i=0;i<branch.len();i++){
     local next=i+1<branch.len()?branch[i+1]:d;
     if(GSMap.DistanceManhattan(branch[i],next)>1){
      if(!GSBridge.IsBridgeTile(branch[i]))GSRoad.BuildRoad(branch[i],next);
     }else GSRoad.BuildRoad(branch[i],next);
    }
    GSLog.Info("P4_DEPOT_SPUR|"+CASE+"|"+branch.len());
   }
  }
  if(depot<0){Fail("depot");return null;}
  GSLog.Info("P4_CAPITAL|"+CASE+"|way_and_depot|"+(afterb-GSCompany.GetBankBalance(CID)));
  local infra=initialcash-GSCompany.GetBankBalance(CID),prefleet=GSCompany.GetBankBalance(CID);account.ResetCosts();
  local v=(MODE=="rail"?GSVehicle.BuildVehicle(depot,ENGINE):GSVehicle.BuildVehicleWithRefit(depot,ENGINE,CARGO));
  if(!GSVehicle.IsValidVehicle(v)){Fail("vehicle/refit");return null;}
  if(MODE=="rail")for(local i=0;i<WAGONS;i++){
   local w=GSVehicle.BuildVehicleWithRefit(depot,CARGO==0 || CARGO==2?1462:1430,CARGO);
   if(!GSVehicle.IsValidVehicle(w) || !GSVehicle.MoveWagon(w,0,v,GSVehicle.GetNumWagons(v)-1)){Fail("wagons");return null;}
  }
  if(MODE=="rail" && BRAKE_VAN){
   local van=GSVehicle.BuildVehicle(depot,1459);
   if(!GSVehicle.IsValidVehicle(van) || !GSVehicle.MoveWagon(van,0,v,GSVehicle.GetNumWagons(v)-1)){Fail("brake van");return null;}
  }
  local fleet=prefleet-GSCompany.GetBankBalance(CID);
  if(MODE=="rail")GSLog.Info("P4_TRAIN_LENGTH|"+CASE+"|"+WAGONS+"|"+GSVehicle.GetLength(v)+"|"+PLATFORM+"|"+GSGameSettings.GetValue("vehicle.max_train_length"));
  GSLog.Info("P4_STATIONS|"+a+"|"+b+"|"+GSStation.GetStationID(a)+"|"+GSStation.GetStationID(b)+"|"+v+"|"+GSVehicle.GetVehicleType(v));
  if(!GSOrder.AppendOrder(v,a,GSOrder.OF_NONE)){Fail("origin order");return null;}
  if(!GSOrder.AppendOrder(v,b,ENDPOINTS=="industry"?GSOrder.OF_UNLOAD|GSOrder.OF_NO_LOAD:GSOrder.OF_NONE)){Fail("destination order");return null;}
  local vehicles=[v];
  for(local i=1;i<FLEET;i++){
   local copyv=GSVehicle.CloneVehicle(depot,v,true);
   if(!GSVehicle.IsValidVehicle(copyv)){Fail("clone fleet");return null;}
   vehicles.append(copyv);
  }
  fleet=prefleet-GSCompany.GetBankBalance(CID);
  GSLog.Info("P4_FLEET|"+CASE+"|"+vehicles.len());
  if(POLICY=="repay_idle"){
   local target=max(0,((GSCompany.GetLoanAmount()-GSCompany.GetBankBalance(CID)+10000+9999)/10000).tointeger()*10000);
   if(target<GSCompany.GetLoanAmount())GSCompany.SetLoanAmount(target);
  }
  GSLog.Info("P4_BUILT|"+CASE+"|"+ENGINE+"|"+GSEngine.GetName(ENGINE)+"|"+infra+"|"+fleet+"|"+GSVehicle.GetCapacity(v,CARGO)+"|"+GSMap.GetTileX(a)+"|"+GSMap.GetTileY(a)+"|"+GSMap.GetTileX(b)+"|"+GSMap.GetTileY(b)+"|"+(path==null?-1:path.len())+"|"+GSCompany.GetBankBalance(CID)+"|"+GSCompany.GetLoanAmount()+"|"+GSDate.GetCurrentDate());
  foreach(vehicle in vehicles)if(!GSVehicle.StartStopVehicle(vehicle)){Fail("start");return null;}

  local after=Ledger(CID);
  local state={cid=CID,tag=CASE,config=ACTIVE,vehicles=vehicles,a=a,b=b,capacity=GSVehicle.GetCapacity(v,CARGO),infra=after[0]-before[0],fleet=after[1]-before[1],samples=0,loaded=0,loadsum=0,cap_sum=0,broken=0,running=0,at_station=0,speed_sum=0,loads=0,arrivals=0,prior_state=-1};
  GSLog.Info("P4_COMMISSION|"+CASE+"|"+CID+"|"+state.infra+"|"+state.fleet+"|"+state.capacity+"|"+vehicles.len()+"|"+GSDate.GetCurrentDate()+"|"+depot);
  return state;
 }
 function Ledger(cid){local out=[];for(local e=0;e<15;e++){local sum=0;for(local y=0;y<3;y++)sum+=GSCompany.GetAnnualExpenseValue(cid,y,e);out.append(sum);}return out;}
}
class TransportProbe extends GSController {
 function Apply(cfg,cid,tag){
  ::ACTIVE=cfg;::MODE=cfg.mode;::CARGO=cfg.cargo;::A=cfg.a;::B=cfg.b;::ENGINE=cfg.engine;::FLEET=cfg.fleet;::ENDPOINTS=cfg.endpoints;::WAGONS=cfg.wagons;::PLATFORM=cfg.platform;::BRAKE_VAN=cfg.brake;::MIN_SEPARATION=cfg.sep;::CASE=tag;
  local builder=RouteBuilder();builder.CID=cid;return builder.Build();
 }
 function Sample(s){
  foreach(v in s.vehicles){
   if(!GSVehicle.IsValidVehicle(v))continue;
   local load=GSVehicle.GetCargoLoad(v,s.config.cargo),state=GSVehicle.GetState(v),speed=GSVehicle.GetCurrentSpeed(v);
   s.samples++;if(load>0)s.loaded++;s.loadsum+=load;s.cap_sum+=GSVehicle.GetCapacity(v,s.config.cargo);
   if(state==GSVehicle.VS_BROKEN)s.broken++;
   if(state==GSVehicle.VS_AT_STATION)s.at_station++;
   if(speed>0)s.running++;
   if(load>0){s.speed_sum+=speed;s.loads++;}
  }
 }
 function Start(){
  local count=CONFIG.routes.len(),services=[],expanded=false;
  while(GSCompany.ResolveCompanyID(count-1)==GSCompany.COMPANY_INVALID)Sleep(2);
  for(local c=0;c<count;c++){
   local mode=GSCompanyMode(c);
   GSLog.Info("P4_START|"+c+"|"+GSCompany.GetBankBalance(c)+"|"+GSCompany.GetLoanAmount()+"|"+GSCompany.GetMaxLoanAmount()+"|"+GSGameSettings.GetValue("economy.infrastructure_maintenance")+"|"+GSGameSettings.GetValue("vehicle.max_train_length"));
   foreach(id in [147,149,150,151,181,402,430,612,614,615,616,617,1534,2038])GSLog.Info("P4_OPENING|"+c+"|"+id+"|"+GSEngine.IsBuildable(id)+"|"+GSEngine.GetName(id)+"|"+GSEngine.GetDesignDate(id));
  }
  local order=[];if("order" in CONFIG)order=CONFIG.order;else for(local c=0;c<count;c++)order.append(c);
  foreach(c in order){
   local s=Apply(CONFIG.routes[c],c,"company_"+c);if(s!=null)services.append(s);
  }
  if(services.len()==0){GSLog.Info("P4_NO_SERVICE");GSLog.Info("P4_DONE");while(true)Sleep(10000);}
  local year=GSDate.GetYear(GSDate.GetCurrentDate()),end=1800+CONFIG.years,month=-1;
  while(year<end){
   foreach(s in services){local mode=GSCompanyMode(s.cid);Sample(s);}
   if(GSDate.GetMonth(GSDate.GetCurrentDate())!=month){
    month=GSDate.GetMonth(GSDate.GetCurrentDate());
    foreach(s in services){local mode=GSCompanyMode(s.cid);
     GSLog.Info("P4_MONTH|"+s.cid+"|"+GSDate.GetCurrentDate()+"|"+GSCompany.GetBankBalance(s.cid)+"|"+GSStation.GetCargoRating(GSStation.GetStationID(s.a),s.config.cargo)+"|"+GSStation.GetCargoWaiting(GSStation.GetStationID(s.a),s.config.cargo));
     foreach(v in s.vehicles)if(GSVehicle.IsValidVehicle(v))GSLog.Info("P4_POSITION|"+s.cid+"|"+v+"|"+GSVehicle.GetLocation(v)+"|"+GSVehicle.GetCurrentSpeed(v)+"|"+GSVehicle.GetCargoLoad(v,s.config.cargo)+"|"+GSVehicle.GetState(v));
    }
   }
   if(GSDate.GetYear(GSDate.GetCurrentDate())!=year){
    Sleep(74);
    for(local c=0;c<count;c++){
     local mode=GSCompanyMode(c),ledger="",delivered=0,profit=0,fleet=0;
     for(local e=0;e<15;e++)ledger+=GSCompany.GetAnnualExpenseValue(c,1,e)+",";
     for(local q=1;q<=4;q++)delivered+=GSCompany.GetQuarterlyCargoDelivered(c,q);
     foreach(s in services)if(s.cid==c)foreach(v in s.vehicles)if(GSVehicle.IsValidVehicle(v)){fleet++;profit+=GSVehicle.GetProfitLastYear(v);}
     GSLog.Info("P4_YEAR|"+c+"|"+year+"|"+GSCompany.GetBankBalance(c)+"|"+GSCompany.GetLoanAmount()+"|"+GSCompany.GetQuarterlyCompanyValue(c,0)+"|"+delivered+"|"+fleet+"|"+profit+"|"+ledger);
    }
    foreach(s in services){
     GSLog.Info("P4_DUTY|"+s.cid+"|"+year+"|"+s.tag+"|"+s.samples+"|"+s.loaded+"|"+s.loadsum+"|"+s.cap_sum+"|"+s.broken+"|"+s.running+"|"+s.at_station+"|"+s.speed_sum+"|"+s.loads);
     s.samples=0;s.loaded=0;s.loadsum=0;s.cap_sum=0;s.broken=0;s.running=0;s.at_station=0;s.speed_sum=0;s.loads=0;
    }
    year=GSDate.GetYear(GSDate.GetCurrentDate());
    if("expand" in CONFIG && CONFIG.expand && !expanded && year>=1810){
